(function () {
  function _integer_from_string(v) {
    if (typeof v === "number") {
      if (!Number.isInteger(v)) {
        throw new Error("expected integer");
      }
      return v;
    }
    if (typeof v === "string") {
      const trimmed = v.trim();
      if (trimmed === "" || !/^-?\\d+$/.test(trimmed)) {
        throw new Error("expected integer");
      }
      const n = Number(trimmed);
      if (!Number.isInteger(n)) {
        throw new Error("expected integer");
      }
      return n;
    }
    throw new Error("expected integer");
  }

  function _integer_to_string(v) {
    return String(_integer_from_string(v));
  }

  return { _integer_from_string, _integer_to_string };
})
